import Foundation
import CRestoreSQLite
public actor RestoreQueue {
 private var db:OpaquePointer?
 private let transient=unsafeBitCast(-1,to:sqlite3_destructor_type.self)
 public init(url:URL)throws{let directory=url.deletingLastPathComponent();try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true,attributes:[.posixPermissions:0o700]);var excluded=directory;var values=URLResourceValues();values.isExcludedFromBackup=true;try excluded.setResourceValues(values)
 #if os(iOS)
 try FileManager.default.setAttributes([.protectionKey:FileProtectionType.completeUntilFirstUserAuthentication],ofItemAtPath:directory.path)
 #endif
 guard sqlite3_open_v2(url.path,&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX,nil)==SQLITE_OK else{throw RestoreFailure.storage};sqlite3_busy_timeout(db,5000);var schema:OpaquePointer?;guard sqlite3_prepare_v2(db,"PRAGMA user_version",-1,&schema,nil)==SQLITE_OK else{throw RestoreFailure.storage};let supported=sqlite3_step(schema)==SQLITE_ROW && sqlite3_column_int(schema,0)<=1;sqlite3_finalize(schema);guard supported else{throw RestoreFailure.storage}
 guard sqlite3_exec(db,"PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; CREATE TABLE IF NOT EXISTS restores(id TEXT PRIMARY KEY,account TEXT NOT NULL,library TEXT NOT NULL,asset TEXT NOT NULL,version TEXT NOT NULL,state TEXT NOT NULL,retry_at REAL,revision INTEGER NOT NULL,record BLOB NOT NULL); CREATE INDEX IF NOT EXISTS restore_page ON restores(account,library,id); CREATE INDEX IF NOT EXISTS restore_due ON restores(account,library,state,retry_at); CREATE UNIQUE INDEX IF NOT EXISTS restore_active ON restores(account,library,asset,version) WHERE state NOT IN ('RESTORED','CANCELLED','FAILED_PERMANENT','RECONCILE_REQUIRED'); PRAGMA user_version=1;",nil,nil,nil)==SQLITE_OK else{throw RestoreFailure.storage};try FileManager.default.setAttributes([.posixPermissions:0o600],ofItemAtPath:url.path)
 }
 deinit{sqlite3_close(db)}
 private func stmt(_ sql:String)throws->OpaquePointer{var s:OpaquePointer?;guard sqlite3_prepare_v2(db,sql,-1,&s,nil)==SQLITE_OK,let s else{throw RestoreFailure.storage};return s}
 private func bind(_ value:String,_ s:OpaquePointer,_ n:Int32){_=value.withCString{sqlite3_bind_text(s,n,$0,-1,transient)}}
 private func data(_ value:RestoreItem,_ s:OpaquePointer,_ n:Int32)throws{let d=try JSONEncoder().encode(value);_=d.withUnsafeBytes{sqlite3_bind_blob(s,n,$0.baseAddress,Int32(d.count),transient)}}
 private func decode(_ s:OpaquePointer)throws->RestoreItem{guard let p=sqlite3_column_blob(s,0) else{throw RestoreFailure.storage};return try JSONDecoder().decode(RestoreItem.self,from:Data(bytes:p,count:Int(sqlite3_column_bytes(s,0))))}
 public func enqueue(_ item:RestoreItem)throws{guard item.state == .queued,item.revision==0,item.evidence.supported,item.localIdentifier==nil else{throw RestoreFailure.unsupported};let count=try stmt("SELECT count(*) FROM restores WHERE state NOT IN ('RESTORED','CANCELLED')");defer{sqlite3_finalize(count)};guard sqlite3_step(count)==SQLITE_ROW,sqlite3_column_int(count,0)<25000 else{throw RestoreFailure.storage};let s=try stmt("INSERT INTO restores VALUES(?,?,?,?,?,?,NULL,0,?)");defer{sqlite3_finalize(s)};for(n,v)in [item.id.uuidString,item.accountID.uuidString,item.libraryID.uuidString,item.evidence.id.uuidString,item.evidence.cloudVersionId,item.state.rawValue].enumerated(){bind(v,s,Int32(n+1))};try data(item,s,7);guard sqlite3_step(s)==SQLITE_DONE else{throw RestoreFailure.duplicate}}
 public func read(_ id:UUID)throws->RestoreItem?{let s=try stmt("SELECT record FROM restores WHERE id=?");defer{sqlite3_finalize(s)};bind(id.uuidString,s,1);let result=sqlite3_step(s);if result==SQLITE_DONE{return nil};guard result==SQLITE_ROW else{throw RestoreFailure.storage};return try decode(s)}
 public func page(account:UUID,library:UUID,after:UUID?=nil,limit:Int=100)throws->[RestoreItem]{guard (1...1000).contains(limit) else{throw RestoreFailure.storage};let s=try stmt("SELECT record FROM restores WHERE account=? AND library=? AND id>? ORDER BY id LIMIT ?");defer{sqlite3_finalize(s)};bind(account.uuidString,s,1);bind(library.uuidString,s,2);bind(after?.uuidString ?? "",s,3);sqlite3_bind_int(s,4,Int32(limit));return try rows(s)}
 public func recent(account:UUID,library:UUID,after:UUID?=nil,limit:Int=100)throws->[RestoreItem]{
  guard (1...1000).contains(limit) else{throw RestoreFailure.storage};var anchor:RestoreItem?
  if let after{guard let item=try read(after),item.accountID==account,item.libraryID==library else{throw RestoreFailure.authorization};anchor=item}
  let created="json_extract(CAST(record AS TEXT),'$.createdAt')"
  let s=try stmt("SELECT record FROM restores WHERE account=? AND library=? AND (? IS NULL OR (\(created),id)<(?,?)) ORDER BY \(created) DESC,id DESC LIMIT ?");defer{sqlite3_finalize(s)}
  bind(account.uuidString,s,1);bind(library.uuidString,s,2)
  if let anchor{sqlite3_bind_double(s,3,anchor.createdAt.timeIntervalSinceReferenceDate);sqlite3_bind_double(s,4,anchor.createdAt.timeIntervalSinceReferenceDate);bind(anchor.id.uuidString,s,5)}else{sqlite3_bind_null(s,3);sqlite3_bind_null(s,4);sqlite3_bind_null(s,5)}
  sqlite3_bind_int(s,6,Int32(limit));return try rows(s)
 }
 private func rows(_ s:OpaquePointer)throws->[RestoreItem]{var result:[RestoreItem]=[];while true{let code=sqlite3_step(s);if code==SQLITE_DONE{return result};guard code==SQLITE_ROW else{throw RestoreFailure.storage};result.append(try decode(s))}}
 public func history(account:UUID,library:UUID,evidence:RestoreEvidence)throws->[RestoreItem]{let s=try stmt("SELECT record FROM restores WHERE account=? AND library=? AND asset=? AND version=? ORDER BY CASE WHEN state='RECONCILE_REQUIRED' THEN 0 WHEN state NOT IN ('RESTORED','CANCELLED','FAILED_PERMANENT') THEN 1 ELSE 2 END,id LIMIT 100");defer{sqlite3_finalize(s)};for(n,v)in [account.uuidString,library.uuidString,evidence.id.uuidString,evidence.cloudVersionId].enumerated(){bind(v,s,Int32(n+1))};return try rows(s)}
 public func due(account:UUID,library:UUID,limit:Int=4)throws->[RestoreItem]{let s=try stmt("SELECT record FROM restores WHERE account=? AND library=? AND state IN ('QUEUED','FAILED_RETRYABLE','READY_TO_SAVE') AND (retry_at IS NULL OR retry_at<=?) ORDER BY retry_at,id LIMIT ?");defer{sqlite3_finalize(s)};bind(account.uuidString,s,1);bind(library.uuidString,s,2);sqlite3_bind_double(s,3,Date().timeIntervalSince1970);sqlite3_bind_int(s,4,Int32(max(1,min(limit,8))));return try rows(s)}
 public func summary(account:UUID,library:UUID)throws->[RestoreState:Int]{let s=try stmt("SELECT state,count(*) FROM restores WHERE account=? AND library=? GROUP BY state");defer{sqlite3_finalize(s)};bind(account.uuidString,s,1);bind(library.uuidString,s,2);var result:[RestoreState:Int]=[:];while sqlite3_step(s)==SQLITE_ROW{if let text=sqlite3_column_text(s,0),let state=RestoreState(rawValue:String(cString:text)){result[state]=Int(sqlite3_column_int64(s,1))}};return result}
 @discardableResult public func save(_ item:RestoreItem)throws->RestoreItem{try update(item,completion:false)}
 public func completed(_ item:RestoreItem,localIdentifier:String)throws->RestoreItem{guard !localIdentifier.isEmpty,localIdentifier.utf8.count<=1024,[.saving,.reconcile].contains(item.state) else{throw RestoreFailure.ambiguousSave};var next=item;next.state = .restored;next.localIdentifier=localIdentifier;next.restoredAt=Date();return try update(next,completion:true)}
 private func update(_ item:RestoreItem,completion:Bool)throws->RestoreItem{guard let old=try read(item.id),old.revision == item.revision else{throw RestoreFailure.stale};guard old.accountID == item.accountID,old.libraryID == item.libraryID,old.evidence == item.evidence,old.createdAt == item.createdAt,old.state != .restored,old.state != .cancelled,item.bytesDownloaded>=0,item.bytesDownloaded<=item.evidence.expectedSize else{throw RestoreFailure.versionChanged};guard completion || old.state.allows(item.state) else{throw RestoreFailure.stale};guard completion || item.state != .restored else{throw RestoreFailure.ambiguousSave};if old.state == .saving && !completion{guard item.state == .reconcile || item.state == .saving else{throw RestoreFailure.ambiguousSave}};if old.state == .reconcile && !completion{guard item.state == .reconcile else{throw RestoreFailure.ambiguousSave}};var next=item;next.revision+=1;next.updatedAt=Date();let s=try stmt("UPDATE restores SET state=?,retry_at=?,revision=?,record=? WHERE id=? AND revision=?");defer{sqlite3_finalize(s)};bind(next.state.rawValue,s,1);if let date=next.nextRetryAt{sqlite3_bind_double(s,2,date.timeIntervalSince1970)}else{sqlite3_bind_null(s,2)};sqlite3_bind_int(s,3,Int32(next.revision));try data(next,s,4);bind(next.id.uuidString,s,5);sqlite3_bind_int(s,6,Int32(item.revision));guard sqlite3_step(s)==SQLITE_DONE,sqlite3_changes(db)==1 else{throw RestoreFailure.stale};return next}
}
